mapper.select:
select id, boardTitle, boardPass, boardContents, deadline, fileAttached,
datediff(deadline, curdate()) as dday, univName, department, info
from board_table where id=#{id}

mapper.update:
update board_table
set boardTitle=#{boardTitle}, boardContents=#{boardContents}, boardPass=#{boardPass}, deadline=#{deadline}
where id=#{id}
